            "INFO",
            "bhavcopy-write-start",
            Some(&format!(
                "kind=batch mode={:?} fromDate={} toDate={} jobs={} calendarSkips={} workers={}",
                normalized_config.mode,
                normalized_config.start_date,
                normalized_config.end_date,
                tasks.len(),
