fn upsert_download_log_entry_once(connection: &Connection, result: &DownloadResult) -> rusqlite::Result<()> {
    if result.success {
        connection
            .execute(
                "
                  INSERT INTO download_log (trade_date, exchange, rows_inserted, max_volume, status, note)
                  VALUES (?, ?, ?, ?, 'ok', NULL)
                  ON CONFLICT(trade_date, exchange) DO UPDATE SET
                    rows_inserted = excluded.rows_inserted,
                    max_volume = excluded.max_volume,
                    downloaded_at = datetime('now'),
                    status = excluded.status,
                    note = NULL
                ",
                params![
                    &result.trade_date,
                    &result.exchange,
                    result.rows_inserted as i64,
                    result.max_volume as i64,
                ],
            )?;
    } else {
        connection
            .execute(
                "
                  INSERT INTO download_log (trade_date, exchange, rows_inserted, max_volume, status, note)
                  VALUES (?, ?, 0, 0, 'error', ?)
                  ON CONFLICT(trade_date, exchange) DO UPDATE SET
                    rows_inserted = excluded.rows_inserted,
                    max_volume = excluded.max_volume,
                    downloaded_at = datetime('now'),
                    status = excluded.status,
                    note = excluded.note
                ",
                params![&result.trade_date, &result.exchange, &result.message],
            )?;
    }

    Ok(())
}

