                    max_volume: parsed_result.max_volume,
                    message,
                };
                let log_result = DownloadResult {
                    rows_inserted: parsed.rows.len(),
                    message: format!(
                        "Imported symbol-batched staged {} records; parsed {} rows",
                        parsed_result.rows_inserted,
                        parsed.rows.len()
                    ),
                    ..result.clone()
                };
