        if active.as_ref().is_some_and(|(_, stop)| Arc::ptr_eq(&self.stop.0, &stop.0)) {
            *active = None;
        }
        self.stop.is_requested()
    }
}

impl Drop for BatchRun<'_> {
    fn drop(&mut self) {
        let mut active = self.controller.active.lock().expect("Bhavcopy batch owner poisoned");
        if active.as_ref().is_some_and(|(_, stop)| Arc::ptr_eq(&self.stop.0, &stop.0)) {
            *active = None;
        }
