#requires -Version 7.0
param([Parameter(Mandatory)][string]$Job, [switch]$ValidateOnly)
$ErrorActionPreference = 'Stop'
$PSNativeCommandUseErrorActionPreference = $false
$env:GIT_OPTIONAL_LOCKS = '0'
