if ($root -cne 'E:\\TA Projects\\EOD Charting Platform') { throw 'Wrong project root' }
$Job = (Resolve-Path -LiteralPath $Job).Path
if (-not $Job.StartsWith((Join-Path $root 'tmp\\UX13_18_'), [StringComparison]::OrdinalIgnoreCase)) { throw 'Wrong job root' }
$records = @(Get-Content -LiteralPath (Join-Path $Job 'source-hashes.json') -Raw | ConvertFrom-Json)
if ($records.Count -ne 18) { throw 'Expected 18 approved source paths' }
$base = '936ac0bde0a6c32a060122b688fe63798cfdef6d'
$head = 'd143b02aa89344b52909c36e0b5cce937a07c865'
$authority = @(git ls-remote origin refs/heads/main refs/pull/23/head)
if ($LASTEXITCODE -or $authority.Count -ne 2) { throw 'Cannot verify source authority' }
if ($authority -cnotcontains "$base\`trefs/heads/main") { throw 'GitHub main pin differs' }
if ($authority -cnotcontains "$head\`trefs/pull/23/head") { throw 'PR #23 pin differs' }
$authority | Set-Content -LiteralPath (Join-Path $Job 'authority.log')
$expected = @(git diff --name-only --diff-filter=M $base $head)
if ($LASTEXITCODE -or $expected.Count -ne 17) { throw 'Pinned scope differs' }
$expected += 'src/components/__tests__/BhavcopyDownloadRerun.test.ts'
if (Compare-Object $expected @($records.path) -CaseSensitive) { throw 'Unexpected path in preview' }
$journal = Join-Path $Job 'execution.log'
function Write-Record([string]$Line) {
    $Line | Tee-Object -FilePath $journal -Append | Write-Host
}
function Get-Sha([string]$Path) { (Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash }
if (-not $ValidateOnly) {
    $proof = Get-Content -LiteralPath (Join-Path $Job 'preview-typecheck-18.log') -Raw
    if ($proof -notmatch '^\\s*EXIT: 0\\s*$') { throw 'Latest preview typecheck has not passed' }
    $entries = for ($i=0; $i -lt $records.Count; $i++) {
        $record = $records[$i]
        $path = Join-Path $root $record.path
        $candidate = Join-Path $Job "preview/$i.merged"
        $original = Join-Path $Job "originals/$i.original"
        if ((Get-Item -LiteralPath $path).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw "Reparse point $path" }
        if ((Get-Sha $path) -cne $record.originalAndLiveSha256 -or (Get-Sha $original) -cne $record.originalAndLiveSha256) { throw "Live or original drift $path" }
        if ((Get-Sha $candidate) -cne $record.cleanPreviewSha256) { throw "Preview drift $path" }
        if (Select-String -LiteralPath $candidate -Pattern '^(<{7}|={7}|>{7}|\\|{7})' -Quiet) { throw "Conflict marker $path" }
        if (@(git ls-files -u -- $record.path).Count -gt 0 -or @(git diff --cached --name-only -- $record.path).Count -gt 0) { throw "Index overlap $path" }
        $originalText = [IO.File]::ReadAllText($original)
        $desiredText = [IO.File]::ReadAllText($candidate)
        if ($originalText.Contains("\`r\`n")) { $desiredText = $desiredText.Replace("\`n","\`r\`n") }
        $encoding = [Text.UTF8Encoding]::new($false)
        $bytes = $encoding.GetBytes($desiredText)
        $previous = [IO.File]::ReadAllBytes($original)
        if ($previous.Length -ge 3 -and $previous[0] -eq 239 -and $previous[1] -eq 187 -and $previous[2] -eq 191) {
            $bytes = [byte[]](@(239,187,191) + $bytes)
        }
        [pscustomobject]@{ Path=$path; Relative=$record.path; Before=$record.originalAndLiveSha256; Bytes=$bytes;
            After=[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)) }
    }
    Write-Record 'PASS: pins, preview hashes, live hashes, markers, staged-index checks and preview typecheck'
    $records.path | Write-Host
    $backup = @(& ./scripts/create-project-backup.ps1 -ShortName UX13_18_Reconciled -Paths $records.path)[-1]
    $manifest = Get-Content -LiteralPath (Join-Path $backup 'backup-manifest.json') -Raw | ConvertFrom-Json
    if ($manifest.fileCount -ne 18) { throw 'Wrong backup scope' }
    foreach ($entry in $entries) {
        if ((Get-Sha (Join-Path $backup $entry.Relative)) -cne $entry.Before -or (Get-Sha $entry.Path) -cne $entry.Before) { throw "Backup or live drift $($entry.Path)" }
    }
    Write-Record "PASS: verified backup $backup"
    $backup | Set-Content -LiteralPath (Join-Path $Job 'backup-path.txt')
    $written = [System.Collections.Generic.List[object]]::new()
    try {
        foreach ($entry in $entries) {
            if ((Get-Sha $entry.Path) -cne $entry.Before) { throw "Concurrent source edit $($entry.Path)" }
            if ($entry.Before -eq $entry.After) { continue }
            $stage = Join-Path $Job ("write-" + $written.Count)
            [IO.File]::WriteAllBytes($stage, $entry.Bytes)
            [IO.File]::Move($stage, $entry.Path, $true)
            $written.Add($entry)
            if ((Get-Sha $entry.Path) -cne $entry.After) { throw "Write verification failed $($entry.Path)" }
        }
    }
    catch {
        foreach ($entry in $written) {
            if ((Get-Sha $entry.Path) -cne $entry.After) { Write-Record "Concurrent change needs manual review $($entry.Path)"; continue }
            $stage = Join-Path $Job ("rollback-" + [Guid]::NewGuid())
            [IO.File]::Copy((Join-Path $backup $entry.Relative), $stage)
            [IO.File]::Move($stage, $entry.Path, $true)
        }
        throw
    }
    $entries | Select-Object Relative, Before, After | ConvertTo-Json | Set-Content -LiteralPath (Join-Path $Job 'applied-hashes.json')
    Write-Record "PASS: integrated $($written.Count) changed source files"
}
if ($ValidateOnly) {
    foreach ($entry in (Get-Content -LiteralPath (Join-Path $Job 'applied-hashes.json') -Raw | ConvertFrom-Json)) {
        if ((Get-Sha (Join-Path $root $entry.Relative)) -cne $entry.After) { throw "Integrated source drift $($entry.Relative)" }
    }
}
function Invoke-NpmCheck([string]$Name,[string[]]$CommandArgs) {
    $log = Join-Path $Job "$Name.log"
    Write-Record "RUN npm $($CommandArgs -join ' ')"
    & npm.cmd @CommandArgs *> $log
    $code = $LASTEXITCODE
    "EXIT: $code" | Add-Content -LiteralPath $log
    Get-Content -LiteralPath $log -Tail 12 | Write-Host
    if ($code -ne 0) { throw "$Name failed (exit $code)" }
    Write-Record "PASS $Name"
}
function Invoke-CargoCheck([string]$Name,[string]$Action,[string[]]$CommandArgs) {
    foreach ($mode in 'Preview','Run') {
        $log = Join-Path $Job "\${Name}_$mode.log"
        Write-Record "RUN shared Cargo $mode $Action $($CommandArgs -join ' ')"
        & ./scripts/Invoke-EOD-SharedCargo.ps1 -Mode $mode -CargoAction $Action -CargoArguments $CommandArgs *> $log
        $marker = 'BUILD01_SHARED_CARGO_COMMAND_PASS'
        if ($mode -eq 'Preview') { $marker = 'BUILD01_SHARED_CARGO_PREVIEW_PASS_NO_BUILD_NO_CHANGES' }
