@'
param([Parameter(Mandatory)][string]$Job)
$ErrorActionPreference='Stop'
$PSNativeCommandUseErrorActionPreference=$false
if((Resolve-Path .).Path -cne 'E:\TA Projects\EOD Charting Platform'){throw 'Wrong project'}
function Step([string]$Name,[string]$Program,[string[]]$Arguments){
    $log=Join-Path $Job "$Name.log"
    "COMMAND: $Program $($Arguments -join ' ')" | Tee-Object -FilePath $log | Write-Host
    & $Program @Arguments *>> $log
    $code=$LASTEXITCODE
    "EXIT: $code" | Add-Content $log
    Get-Content $log -Tail 9 | Write-Host
    if($code -ne 0){throw "$Name failed: $code"}
}
function Cargo([string]$Name,[string]$Action,[string[]]$Arguments){
    foreach($mode in @('Preview','Run')){
        $log=Join-Path $Job "${Name}_$mode.log"
        "RUN $mode cargo $Action $($Arguments -join ' ')" | Write-Host
        try {
            & ./scripts/Invoke-EOD-SharedCargo.ps1 -Mode $mode -CargoAction $Action -CargoArguments $Arguments *> $log
        } catch {
            "FAIL: $_" | Add-Content $log
            Get-Content $log -Tail 30 | Write-Host
            throw
        }
        $marker='BUILD01_SHARED_CARGO_COMMAND_PASS'
        if($mode -eq 'Preview'){$marker='BUILD01_SHARED_CARGO_PREVIEW_PASS_NO_BUILD_NO_CHANGES'}
        if(-not (Select-String -LiteralPath $log -Pattern $marker -SimpleMatch -Quiet)){throw "$Name $mode missing PASS marker"}
        'EXIT: 0' | Add-Content $log
        Get-Content $log -Tail 8 | Write-Host
    }
}
