$secretLine = $credential | Where-Object { $_.StartsWith('password=') } | Select-Object -First 1
if(-not $secretLine){throw 'GitHub REST credential unavailable'}
$token = ConvertTo-SecureString $secretLine.Substring(9) -AsPlainText -Force
$api='https://api.github.com/repos/dhamnaik-lab/Eod-Charting-Platform'
function Read-GitHub([string]$Path){
