text(await tools.exec_command({cmd:`$ErrorActionPreference='Stop'; $j=Get-Content tmp/ux13-pr23-job.txt; & "$j/Verify-PR23-Remote.ps1" -Job $j *> "$j/github-verification.log"; if(-not $?){throw 'Remote verification failed'}; Get-Content "$j/github-verification.log" -Tail 24; $checks=Get-Content "$j/github-checks.json" -Raw|ConvertFrom-Json; $workflows=Get-Content "$j/github-workflows.json" -Raw|ConvertFrom-Json; "Check runs: $($checks.total_count); workflow runs: $($workflows.total_count)"; $before=@(Get-Content "$j/local-status-before.txt"); $now=@(git status --porcelain=v1 --untracked-files=normal); if(Compare-Object $before $now -CaseSensitive){throw 'Active checkout status changed'}; if((git rev-parse HEAD).Trim() -cne (Get-Content "$j/local-head-before.txt").Trim()){throw 'Active HEAD changed'}; 'PASS active checkout HEAD and status' | Set-Content "$j/local-preservation.log"
@'
from pathlib import Path
import hashlib,json,subprocess,sys
j=Path(sys.argv[1]); p=j/'candidate'
head=(j/'commit.txt').read_text().strip()
def git(*args):
    return subprocess.check_output(['git','-C',str(p),*args])
sha=lambda b: hashlib.sha256(b).hexdigest().upper()
expected={x['path']:x for x in json.loads((j/'staged-hashes.json').read_text())}
remote=json.loads((j/'github-file-verification.json').read_text(encoding='utf-8-sig'))
for row in remote:
    name=row['path']
    b=git('show',head+':'+name)
    row['sourceSha256']=sha(b)
    if name in expected:
        assert row['sourceSha256']==expected[name]['expectedGitBlobSha256'], name
    assert git('rev-parse',head+':'+name).decode().strip()==row['gitHubBlob'], name
for name, row in expected.items():
    assert sha(Path(name).read_bytes())==row['liveSha256'], name
(j/'github-file-verification.json').write_text(json.dumps(remote,indent=2)+'\\n',encoding='utf-8')
print('PASS all',len(remote),'GitHub blob IDs and source hashes; all',len(expected),'projected live source hashes preserved')
'@ | python - $j | Tee-Object -FilePath "$j/committed-source-verification.log"
if($LASTEXITCODE){throw 'Final source verification failed'}`,yield_time_ms:1000,max_output_tokens:1200}))
